  var growth_rate2 := Math.Pow(4.0, 1.0/3.0); // ∛4 ≈ 1.587

  // Calculate populations at time t
  p1 := initial_population * Math.Pow(growth_rate1, t);
  p2 := initial_population * Math.Pow(growth_rate2, t);

  // Calculate ratio
